namespace Interoper.Generator;

/// <summary>What <see cref="Bindings.Write"/> changed, relative to the folder, with <c>/</c>.</summary>
public sealed record BindingChanges(IReadOnlyList<string> Written, IReadOnlyList<string> Deleted);

/// <summary>Writes generated files to a folder (design §5): the CLI's and the golden slice's one code path.</summary>
public static class Bindings
{
    /// <summary>The first line of every file the generator writes (design §4).</summary>
    public const string Header = "// <auto-generated/>";

    /// <summary>The CLI's own folder in the output: the IR cache and the manifest.</summary>
    public const string CacheFolder = ".interoper";

    /// <summary>The paths the last run wrote, one per line, relative to the output folder.</summary>
    public const string ManifestFile = "files.txt";

    /// <summary>
    /// <see cref="Write"/> with the folder's manifest (<c>.interoper/files.txt</c>) as <c>previous</c>, then records
    /// what this run produced in it. A folder without one has nothing deleted.
    /// </summary>
    public static BindingChanges WriteTracked(string folder, IReadOnlyList<GeneratedFile> files)
    {
        var manifest = Path.Combine(folder, CacheFolder, ManifestFile);
        string[] previous = File.Exists(manifest) ? File.ReadAllLines(manifest) : [];
        var changes = Write(folder, files, previous);
        Directory.CreateDirectory(Path.GetDirectoryName(manifest)!);
        File.WriteAllLines(manifest, files.Select(f => f.Path).Order(StringComparer.Ordinal));
        return changes;
    }

    /// <summary>
    /// First deletes each of <paramref name="previous"/> (paths relative to the folder) that this run doesn't produce
    /// and that still starts with <see cref="Header"/>, with the folders that leaves empty; then writes each file whose
    /// text differs, so an unchanged one keeps its timestamp. Deleting first means a case-only rename
    /// (<c>Mapview.cs</c> → <c>MapView.cs</c>) gets the new name on a case-insensitive file system too. Nothing else in
    /// the folder is looked at.
    /// </summary>
    /// <exception cref="InvalidDataException">A file's path leaves the folder, or two differ only in case.</exception>
    public static BindingChanges Write(string folder, IReadOnlyList<GeneratedFile> files, IEnumerable<string> previous)
    {
        folder = Path.TrimEndingDirectorySeparator(Path.GetFullPath(folder));
        var produced = new HashSet<string>(StringComparer.Ordinal);
        var caseless = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var file in files)
        {
            var path = Inside(folder, file.Path) ?? throw new InvalidDataException($"The generated path {file.Path} isn't inside {folder}.");
            if (!caseless.Add(path))
            {
                throw new InvalidDataException($"The generated paths include {file.Path} twice, or twice in different cases.");
            }
            produced.Add(path);
        }

        var deleted = new List<string>();
        foreach (var relative in previous.Where(p => p.Length > 0).Distinct().Order(StringComparer.Ordinal))
        {
            var path = Inside(folder, relative);
            if (path is null || produced.Contains(path) || !IsGenerated(path))
            {
                continue;
            }
            File.Delete(path);
            deleted.Add(relative);
            for (var dir = Path.GetDirectoryName(path)!; dir.Length > folder.Length && !Directory.EnumerateFileSystemEntries(dir).Any(); dir = Path.GetDirectoryName(dir)!)
            {
                Directory.Delete(dir);
            }
        }

        var written = new List<string>();
        foreach (var file in files)
        {
            var path = Path.GetFullPath(Path.Combine(folder, file.Path));
            if (!File.Exists(path) || File.ReadAllText(path) != file.Text)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path)!);
                File.WriteAllText(path, file.Text);
                written.Add(file.Path);
            }
        }
        return new(written, deleted);
    }

    /// <summary>The full path of <paramref name="relative"/> in <paramref name="folder"/>, or null when it leaves it.</summary>
    private static string? Inside(string folder, string relative)
    {
        if (Path.IsPathRooted(relative))
        {
            return null;
        }
        var path = Path.GetFullPath(Path.Combine(folder, relative));
        return path.StartsWith(folder + Path.DirectorySeparatorChar, StringComparison.Ordinal) ? path : null;
    }

    private static bool IsGenerated(string path)
    {
        if (!File.Exists(path))
        {
            return false;
        }
        using var reader = new StreamReader(path);
        return reader.ReadLine() == Header;
    }
}
